using QuantForge.Governance; using Xunit; namespace QuantForge.ArchitectureTests; public class LiveSessionLeaseV22_60ArchitectureChecks { [Fact] public void LeaseRequiresMatchingAuthority(){var t=DateTimeOffset.UtcNow;var l=new LiveSessionLeaseV22_60("s",t.AddMinutes(-1),t.AddMinutes(5),"a");Assert.True(LiveSessionLeaseGateV22_60.IsValid(l,t,"a"));Assert.False(LiveSessionLeaseGateV22_60.IsValid(l,t,"b"));} [Fact] public void ExpiredLeaseCannotRenew(){var t=DateTimeOffset.UtcNow;var l=new LiveSessionLeaseV22_60("s",t.AddMinutes(-10),t.AddMinutes(-1),"a");Assert.False(LiveSessionLeaseGateV22_60.CanRenew(l,t,"a"));}}
